#!/usr/bin/env python3
"""Builds the documentation site.

Renders every Markdown page in docs/ with the site template, and drops the API
reference generated by Doxygen next to them under /api/.

The reference comes from CMake, so it has to be built first:

    cmake -S . -B build -DOPENANIMA_ENABLE_DOCS=ON
    cmake --build build --target docs
    python3 .github/scripts/build_docs.py

Usage: build_docs.py [output-directory]        (default: build/site)

Environment overrides:
    PANDOC    pandoc executable to use         (default: pandoc from PATH)
    API_SRC   directory holding the reference  (default: build/docs/html)
"""

import os
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DOCS = ROOT / "docs"
SITE = DOCS / "site"

PANDOC_ARGS = [
    "--from",
    "gfm",
    "--to",
    "html5",
    "--standalone",
    "--metadata",
    "lang=en",
    "--template",
    str(SITE / "template.html"),
    "--css",
    "style.css",
    # Newer pandoc versions call this --syntax-highlighting and warn about the old
    # name. The old name is the one the pandoc in the CI image understands.
    "--highlight-style",
    "tango",
]

# Shown instead of the reference when it has not been generated. A dead link is
# worse than a page that says what to run.
FALLBACK_PAGE = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>API reference pending</title>
<link rel="stylesheet" href="../style.css">
</head>
<body>
<main class="wrap"><article class="doc">
<h1>API reference pending</h1>
<p>The reference has not been generated yet. It is built by Doxygen, through CMake:</p>
<pre><code>cmake -S . -B build -DOPENANIMA_ENABLE_DOCS=ON
cmake --build build --target docs
python3 .github/scripts/build_docs.py</code></pre>
<p><a href="../index.html">Back to the start</a></p>
</article></main>
</body>
</html>
"""


def page_title(markdown: Path) -> str:
    """Returns the first heading of the file, or its stem when there is none."""
    first_line = markdown.read_text(encoding="utf-8").splitlines()[0]
    return first_line.lstrip("# ").strip() or markdown.stem


def render_pages(out: Path, pandoc: str) -> None:
    for page in sorted(DOCS.glob("*.md")):
        command = [pandoc, str(page), *PANDOC_ARGS]
        # The landing page is short enough to be read without an index on the side.
        if page.stem != "index":
            command += ["--toc", "--toc-depth=2"]
        command += ["--metadata", f"title={page_title(page)}", "-o", str(out / f"{page.stem}.html")]

        print(f"    {page.name} -> {page.stem}.html")
        subprocess.run(command, check=True)


def copy_reference(out: Path, reference: Path) -> None:
    if not reference.is_dir():
        print(f"==> no API reference in {reference}")
        print("    generate it with: cmake --build build --target docs")
        (out / "api").mkdir(parents=True)
        (out / "api" / "index.html").write_text(FALLBACK_PAGE, encoding="utf-8")
        return

    print(f"==> API reference: {reference} -> {out / 'api'}")
    shutil.copytree(reference, out / "api")


def main() -> int:
    out = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else ROOT / "build/site"
    reference = Path(os.environ.get("API_SRC", ROOT / "build/docs/html")).resolve()
    pandoc = os.environ.get("PANDOC", "pandoc")

    if shutil.which(pandoc) is None:
        print(f"ERROR: '{pandoc}' not found. Install it from https://pandoc.org", file=sys.stderr)
        return 1

    print(f"==> Site: {out}")
    if out.exists():
        shutil.rmtree(out)
    out.mkdir(parents=True)

    shutil.copy(SITE / "style.css", out / "style.css")
    (out / ".nojekyll").touch()

    print("==> Pages: pandoc")
    render_pages(out, pandoc)

    copy_reference(out, reference)

    print(f"\nDone. To preview it locally:\n  python3 -m http.server -d {out} 8000")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
